 self.backgroundColor=UIColor.clearColor;self.selectionStyle=UITableViewCellSelectionStyleNone;self.card=[PMOfficialCard new];[self.contentView addSubview:self.card];self.cover=[UIImageView new];self.cover.contentMode=UIViewContentModeScaleAspectFill;self.cover.clipsToBounds=YES;self.cover.backgroundColor=[UIColor colorWithWhite:.25 alpha:1];self.cover.tintColor=UIColor.whiteColor;[self.card addSubview:self.cover];self.nameLabel=[UILabel new];self.nameLabel.font=[UIFont systemFontOfSize:20 weight:UIFontWeightSemibold];self.nameLabel.textColor=UIColor.whiteColor;self.nameLabel.numberOfLines=2;[self.card addSubview:self.nameLabel];self.detailLabel=[UILabel new];self.detailLabel.font=[UIFont systemFontOfSize:12];self.detailLabel.textColor=[UIColor colorWithWhite:1 alpha:.65];self.detailLabel.numberOfLines=2;[self.card addSubview:self.detailLabel];self.badge=[UILabel new];self.badge.textAlignment=NSTextAlignmentCenter;self.badge.font=[UIFont boldSystemFontOfSize:16];self.badge.textColor=UIColor.whiteColor;[self.card addSubview:self.badge];self.isAccessibilityElement=YES;}return self;}
- (void)layoutSubviews{[super layoutSubviews];self.card.frame=CGRectInset(self.contentView.bounds,10,6);CGFloat w=self.card.bounds.size.width,h=self.card.bounds.size.height,cover=MIN(170,w*.25);self.cover.frame=CGRectMake(30,8,cover,h-16);self.nameLabel.frame=CGRectMake(cover+46,12,MAX(40,w-cover-148),48);self.detailLabel.frame=CGRectMake(cover+46,62,MAX(40,w-cover-148),32);self.badge.frame=CGRectMake(w-86,30,58,44);}
