@implementation PMContentController
- (void)viewDidLoad{[super viewDidLoad];self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;self.tableView.backgroundColor=[UIColor colorWithRed:.04 green:.055 blue:.075 alpha:1];self.tableView.separatorStyle=UITableViewCellSeparatorStyleNone;self.tableView.rowHeight=124;self.tableView.contentInset=UIEdgeInsetsMake(10,0,20,0);self.title=@"PhiMod \u8c31\u5e93 / \u7ae0\u8282";self.worker=dispatch_queue_create("phimod.content.import",dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL,QOS_CLASS_UTILITY,0));self.pages=[[UISegmentedControl alloc]initWithItems:@[@"\u8c31\u5e93",@"\u7ae0\u8282",@"\u539f\u7248"]];self.pages.selectedSegmentIndex=0;[self.pages addTarget:self action:@selector(reload) forControlEvents:UIControlEventValueChanged];self.navigationItem.titleView=self.pages;self.navigationItem.leftBarButtonItems=@[[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemClose target:self action:@selector(close)],[[UIBarButtonItem alloc]initWithTitle:@"\u56de\u6536\u7ad9" style:UIBarButtonItemStylePlain target:self action:@selector(openTrash)]];UIBarButtonItem*add=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(add)];UIBarButtonItem*select=[[UIBarButtonItem alloc]initWithTitle:@"选择" style:UIBarButtonItemStylePlain target:self action:@selector(toggleBulkSelection)];self.navigationItem.rightBarButtonItems=@[select,add];self.selectedSongIDs=[NSMutableSet new];self.search=[[UISearchController alloc]initWithSearchResultsController:nil];self.search.obscuresBackgroundDuringPresentation=NO;self.search.searchResultsUpdater=self;self.navigationItem.searchController=self.search;self.definesPresentationContext=YES;self.toolbarItems=@[[[UIBarButtonItem alloc]initWithTitle:@"导入 ZIP / PEZ" style:UIBarButtonItemStylePlain target:self action:@selector(importFiles)],[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],[[UIBarButtonItem alloc]initWithTitle:@"应用到游戏" style:UIBarButtonItemStylePlain target:self action:@selector(apply)]];self.navigationController.toolbarHidden=NO;[self reload];}
- (void)message:(NSString*)text {UIAlertController*a=[UIAlertController alertControllerWithTitle:@"PhiMod" message:text preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"确定" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)openTrash{if(!self.busy)PMShowTrash(self);}
- (void)close {if(self.busy){[self message:@"正在处理文件，请等待任务完成"];return;}[self dismissViewControllerAnimated:YES completion:nil];}
- (void)reload {if(self.pages.selectedSegmentIndex!=0&&self.bulkSelection){self.bulkSelection=NO;[self.selectedSongIDs removeAllObjects];}self.db=[PMContentStore.shared snapshot];NSArray*all=self.pages.selectedSegmentIndex==1?self.db[@"chapters"]:self.pages.selectedSegmentIndex==2?[PMHookBackend contentSnapshot][@"chapters"]:self.db[@"songs"];NSMutableArray*filtered=[NSMutableArray new];NSString*q=self.search.searchBar.text.lowercaseString ?: @"";for(NSDictionary*x in all){NSString*hay=[NSString stringWithFormat:@"%@ %@ %@ %@",x[@"title"] ?: x[@"songInfo"][@"title"] ?: x[@"name"],x[@"composer"] ?: @"",x[@"id"] ?: x[@"chapterCode"],x[@"level"] ?: @""];if(!q.length||[hay.lowercaseString containsString:q])[filtered addObject:x];}self.items=filtered;UIBarButtonItem*select=[[UIBarButtonItem alloc]initWithTitle:self.bulkSelection?@"完成选择":@"选择" style:UIBarButtonItemStylePlain target:self action:@selector(toggleBulkSelection)];UIBarButtonItem*add=self.navigationItem.rightBarButtonItems.lastObject ?: [[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(add)];select.enabled=self.pages.selectedSegmentIndex==0&&!self.busy;self.navigationItem.rightBarButtonItems=@[select,add];self.navigationItem.prompt=self.busy?@"正在导入文件…":self.bulkSelection?@"选择多首谱面，再批量导出或删除":@"Changes are saved locally; Apply to Game returns to Chapter Selector";[self updateToolbar];[self.tableView reloadData];}
