- (NSInteger)tableView:(UITableView*)table numberOfRowsInSection:(NSInteger)section{return self.items.count;}
- (UITableViewCell*)tableView:(UITableView*)table cellForRowAtIndexPath:(NSIndexPath*)index{
 PMContentCell*c=(PMContentCell*)[table dequeueReusableCellWithIdentifier:@"officialItem"];if(!c)c=[[PMContentCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:@"officialItem"];NSDictionary*x=self.items[index.row];BOOL chapter=self.pages.selectedSegmentIndex!=0;c.nameLabel.text=chapter?(x[@"name"] ?: x[@"songInfo"][@"title"]):x[@"title"];c.detailLabel.text=chapter?[NSString stringWithFormat:@"%@ · %lu 首",x[@"id"] ?: x[@"chapterCode"],(unsigned long)[(x[@"songs"] ?: x[@"songInfo"][@"songs"])count]]:[NSString stringWithFormat:@"%@ %@ · %@ · %@",x[@"level"],PMDifficultyText(x),x[@"sourceFormat"] ?: @"JSON",x[@"composer"] ?: @""];NSString*folder=[PMContentStore.shared coverFolder:x[@"id"]?:x[@"chapterCode"]];UIImage*image=folder?[UIImage imageWithContentsOfFile:[folder stringByAppendingPathComponent:@"image.png"]]:nil;c.cover.image=image ?: [UIImage systemImageNamed:chapter?@"rectangle.stack":@"music.note"];c.cover.contentMode=image?UIViewContentModeScaleAspectFill:UIViewContentModeCenter;c.badge.text=chapter?@"›":x[@"level"];NSDictionary*colors=@{@"EZ":[UIColor colorWithRed:0 green:.7 blue:.25 alpha:1],@"HD":[UIColor colorWithRed:0 green:.5 blue:1 alpha:1],@"IN":[UIColor colorWithRed:.8 green:.1 blue:.3 alpha:1],@"AT":[UIColor colorWithWhite:.25 alpha:1]};c.badge.backgroundColor=chapter?UIColor.clearColor:(colors[x[@"level"] ?: @""] ?: UIColor.darkGrayColor);NSArray*rgb=PMDifficultyRGB(x[@"difficultyRGB"]?:@"");if(!chapter&&rgb.count==3)c.badge.backgroundColor=[UIColor colorWithRed:[rgb[0]doubleValue]/255. green:[rgb[1]doubleValue]/255. blue:[rgb[2]doubleValue]/255. alpha:1];c.accessoryType=self.bulkSelection&&[self.selectedSongIDs containsObject:x[@"id"]]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;c.accessibilityLabel=[NSString stringWithFormat:@"%@，%@",c.nameLabel.text,c.detailLabel.text];c.accessibilityHint=@"打开谱面或章节操作";return c;
}
- (void)toggleBulkSelection{if(self.busy||self.pages.selectedSegmentIndex!=0)return;self.bulkSelection=!self.bulkSelection;if(!self.bulkSelection)[self.selectedSongIDs removeAllObjects];[self reload];}
- (void)updateToolbar {
    if (!self.bulkSelection) {
        self.toolbarItems = @[
            [[UIBarButtonItem alloc] initWithTitle:@"Import ZIP / PEZ" style:UIBarButtonItemStylePlain target:self action:@selector(importFiles)],
            [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],
            [[UIBarButtonItem alloc] initWithTitle:@"\u5e94\u7528\u5230\u6e38\u620f" style:UIBarButtonItemStylePlain target:self action:@selector(apply)]
        ];
        return;
    }
    NSString *selectTitle = self.selectedSongIDs.count == self.items.count ? @"\u53d6\u6d88\u5168\u9009" : @"\u5168\u9009";
    UIBarButtonItem *all = [[UIBarButtonItem alloc] initWithTitle:selectTitle style:UIBarButtonItemStylePlain target:self action:@selector(toggleSelectAll)];
    UIBarButtonItem *exportButton = [[UIBarButtonItem alloc] initWithTitle:[NSString stringWithFormat:@"\u5bfc\u51fa (%lu)", (unsigned long)self.selectedSongIDs.count] style:UIBarButtonItemStylePlain target:self action:@selector(exportSelected)];
    exportButton.enabled = self.selectedSongIDs.count > 0 && !self.busy;
    UIBarButtonItem *remove = [[UIBarButtonItem alloc] initWithTitle:[NSString stringWithFormat:@"\u5220\u9664 (%lu)", (unsigned long)self.selectedSongIDs.count] style:UIBarButtonItemStyleDone target:self action:@selector(removeSelected)];
    remove.tintColor = UIColor.systemRedColor;
    remove.enabled = self.selectedSongIDs.count > 0 && !self.busy;
    UIBarButtonItem*move=[[UIBarButtonItem alloc]initWithTitle:@"\u79fb\u52a8\u5230\u7ae0\u8282" style:UIBarButtonItemStylePlain target:self action:@selector(moveSelected)];move.enabled=self.selectedSongIDs.count>0&&!self.busy;
    self.toolbarItems = @[all,move,
        [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],
        exportButton,
        [[UIBarButtonItem alloc] initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil],
        remove];
}
- (void)moveSelected{if(self.busy||!self.selectedSongIDs.count)return;NSArray*ids=self.selectedSongIDs.allObjects;PMChooseChapter(self,^(NSString*chapter){NSError*error=nil;if(![PMContentStore.shared assignSongs:ids toChapter:chapter move:YES error:&error])[self message:error.localizedDescription];else{[self.selectedSongIDs removeAllObjects];[self reload];}});}
- (void)toggleSelectAll{if(self.selectedSongIDs.count==self.items.count)[self.selectedSongIDs removeAllObjects];else{[self.selectedSongIDs removeAllObjects];for(NSDictionary*song in self.items)if([song[@"id"] isKindOfClass:NSString.class])[self.selectedSongIDs addObject:song[@"id"]];}[self.tableView reloadData];[self updateToolbar];}
- (void)removeSelected{if(self.busy||!self.selectedSongIDs.count)return;NSArray*ids=self.selectedSongIDs.allObjects;UIAlertController*confirm=[UIAlertController alertControllerWithTitle:@"批量删除谱面" message:[NSString stringWithFormat:@"将删除 %lu 首谱面，并把资源移入回收目录。",(unsigned long)ids.count] preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"Delete" style:UIAlertActionStyleDestructive handler:^(UIAlertAction*a){self.busy=YES;[self reload];dispatch_async(self.worker,^{NSError*error=nil;BOOL ok=[PMContentStore.shared removeSongs:ids error:&error];dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;if(ok)[self.selectedSongIDs removeAllObjects];[self reload];if(!ok)[self message:error.localizedDescription ?: @"批量删除失败"];});});}]];[self presentViewController:confirm animated:YES completion:nil];}
- (void)exportSelected{if(self.busy||!self.selectedSongIDs.count)return;NSArray*ids=self.selectedSongIDs.allObjects;self.busy=YES;[self reload];dispatch_async(self.worker,^{NSMutableArray<NSURL*>*urls=[NSMutableArray new];NSError*error=nil;for(NSString*songID in ids){NSURL*url=nil;@autoreleasepool{url=[PMContentStore.shared exportSong:songID error:&error];}if(!url)break;[urls addObject:url];}dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[self reload];if(error||urls.count!=ids.count){[PMContentStore.shared cleanupExports:urls];[self message:error.localizedDescription ?: @"批量导出失败"];return;}UIActivityViewController*share=[[UIActivityViewController alloc]initWithActivityItems:urls applicationActivities:nil];share.completionWithItemsHandler=^(UIActivityType type,BOOL completed,NSArray*items,NSError*error){[PMContentStore.shared cleanupExports:urls];};share.popoverPresentationController.barButtonItem=self.toolbarItems.count>2?self.toolbarItems[2]:nil;[self presentViewController:share animated:YES completion:nil];});});}
- (void)sheet:(UIAlertController*)a row:(NSIndexPath*)index{a.popoverPresentationController.sourceView=self.tableView;a.popoverPresentationController.sourceRect=[self.tableView rectForRowAtIndexPath:index];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (BOOL)save:(NSDictionary*)db{NSError*e=nil;BOOL ok=[PMContentStore.shared commit:db error:&e];if(!ok)[self message:e.localizedDescription];[self reload];return ok;}
- (void)tableView:(UITableView*)table didSelectRowAtIndexPath:(NSIndexPath*)index{[table deselectRowAtIndexPath:index animated:YES];if(self.busy)return;NSDictionary*x=self.items[index.row];if(self.bulkSelection&&self.pages.selectedSegmentIndex==0){NSString*songID=x[@"id"];if([self.selectedSongIDs containsObject:songID])[self.selectedSongIDs removeObject:songID];else[self.selectedSongIDs addObject:songID];[self.tableView reloadRowsAtIndexPaths:@[index] withRowAnimation:UITableViewRowAnimationNone];[self updateToolbar];return;}NSString*id=x[@"id"] ?: x[@"chapterCode"];BOOL chapter=self.pages.selectedSegmentIndex!=0;UIAlertController*a=[UIAlertController alertControllerWithTitle:chapter?(x[@"name"] ?: x[@"songInfo"][@"title"]):x[@"title"] message:nil preferredStyle:UIAlertControllerStyleActionSheet];
 [a addAction:[UIAlertAction actionWithTitle:chapter?@"打开原版选曲":@"播放此谱面" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){NSDictionary*r=[PMHookBackend contentCommand:chapter?@"chapter":@"play" identifier:id slot:[@[@"EZ",@"HD",@"IN",@"AT"]indexOfObject:x[@"level"]]];if([r[@"ok"] boolValue])[self dismissViewControllerAnimated:YES completion:nil];else[self message:r[@"message"]];}]];
