- (void)edit:(NSDictionary*)item chapter:(BOOL)chapter{BOOL official=self.pages.selectedSegmentIndex==2;NSArray*keys=chapter?@[@"name",@"subtitle",@"banner"]:@[@"title",@"composer",@"charter",@"illustrator",@"level",@"difficulty",@"offsetMs",@"preview",@"previewEnd",@"difficultyRGB"];NSArray*titles=chapter?@[@"章节名称",@"副标题",@"横幅"]:@[@"曲名",@"曲师",@"谱师",@"画师",@"难度名称（也可自定义）",@"难度显示（数字或文字）",@"偏移 / ms",@"预览起点 / 秒",@"预览终点 / 秒",@"选框 RGB：255,128,0（留空用 AT）"];UIAlertController*a=[UIAlertController alertControllerWithTitle:@"编辑信息" message:@"保存后点击应用到游戏" preferredStyle:UIAlertControllerStyleAlert];for(NSUInteger i=0;i<keys.count;++i){[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.placeholder=titles[i];id value=item[keys[i]];if(!chapter&&i==5)value=PMDifficultyText(item);if(official){NSString*key=[@{@"name":@"title",@"subtitle":@"subTitle",@"banner":@"banner"} objectForKey:keys[i]];value=item[@"songInfo"][key];}f.text=[value description] ?: @"";if(i>=6)f.keyboardType=UIKeyboardTypeNumbersAndPunctuation;}];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction*action){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy],*edited=[item mutableCopy];for(NSUInteger i=0;i<keys.count;++i){NSString*v=a.textFields[i].text ?: @"";if(!chapter&&i>=6&&i<=8){NSScanner*scanner=[NSScanner scannerWithString:v];double value=0;if(![scanner scanDouble:&value]||!scanner.isAtEnd||!std::isfinite(value)){[self message:@"数值格式无效"];return;}edited[keys[i]]=@(value);}else edited[keys[i]]=v;}if(!chapter){NSString*name=PMDifficultyName(edited[@"level"]);if(name.length>32||[name rangeOfCharacterFromSet:NSCharacterSet.controlCharacterSet].location!=NSNotFound){[self message:@"难度名称最多32字，不能包含控制字符"];return;}int stock=PMStockDifficulty(name);edited[@"level"]=stock<0?name:name.uppercaseString;edited[@"difficultyText"]=[edited[@"difficulty"]description]?:@"";edited[@"difficulty"]=@(PMDifficultyNumber(edited[@"difficultyText"]));if(!PMDifficultyRGB(edited[@"difficultyRGB"]?:@"")){[self message:@"RGB 请填写三个 0–255 整数，以英文逗号分隔"];return;}}if(official){NSMutableDictionary*overrides=[d[@"chapterOverrides"]mutableCopy] ?: [NSMutableDictionary new];NSMutableDictionary*patch=[overrides[item[@"chapterCode"]]mutableCopy]?:[NSMutableDictionary new];patch[@"title"]=edited[@"name"];patch[@"subTitle"]=edited[@"subtitle"];patch[@"banner"]=edited[@"banner"];overrides[item[@"chapterCode"]]=patch;d[@"chapterOverrides"]=overrides;}else{NSMutableArray*list=[d[chapter?@"chapters":@"songs"]mutableCopy];for(NSUInteger i=0;i<list.count;++i)if([list[i][@"id"] isEqualToString:item[@"id"]])list[i]=edited;d[chapter?@"chapters":@"songs"]=list;}[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)add {if(self.busy)return;if(self.pages.selectedSegmentIndex==0){[self importFiles];return;}UIAlertController*a=[UIAlertController alertControllerWithTitle:@"新建章节" message:nil preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.placeholder=@"章节名称";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"创建" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSString*name=a.textFields.firstObject.text;if(!name.length)return;NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];NSMutableArray*c=[d[@"chapters"]mutableCopy];NSString*id=[@"pm_" stringByAppendingString:[NSUUID.UUID.UUIDString stringByReplacingOccurrencesOfString:@"-" withString:@""]];[c addObject:@{@"id":id,@"name":name,@"subtitle":@"LOCAL CHARTS",@"songs":@[]}];d[@"chapters"]=c;[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)move:(NSString*)identifier index:(NSIndexPath*)index{PMChooseChapter(self,^(NSString*chapter){NSError*error=nil;if(![PMContentStore.shared assignSongs:@[identifier] toChapter:chapter move:YES error:&error])[self message:error.localizedDescription];[self reload];});}

- (void)group:(NSDictionary*)song{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"多难度分组" message:@"填写另一谱面的 ID 合并为同一首；留空恢复独立。原版同难度以最后选择为准；额外难度追加到目标歌曲后。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField*f){f.text=song[@"groupId"];f.placeholder=@"pm_... 或原版歌曲 ID";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存并选用此版本" style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSString*group=a.textFields.firstObject.text.length?a.textFields.firstObject.text:song[@"id"];NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];for(NSMutableDictionary*s in d[@"songs"])if([s[@"id"] isEqualToString:song[@"id"]])s[@"groupId"]=group;NSMutableDictionary*choices=[d[@"chartSelections"]mutableCopy] ?: [NSMutableDictionary new];int slot=PMStockDifficulty(song[@"level"]);if(slot>=0)choices[[NSString stringWithFormat:@"%@@%d",group,slot]]=song[@"id"];else{NSInteger order=0;for(NSDictionary*v in d[@"songs"])if([v[@"groupId"]isEqualToString:group])order=MAX(order,[v[@"difficultyOrder"]integerValue]+1);for(NSMutableDictionary*v in d[@"songs"])if([v[@"id"]isEqualToString:song[@"id"]])v[@"difficultyOrder"]=@(order);}d[@"chartSelections"]=choices;[self save:d];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)orderChapter:(NSString*)identifier{UIAlertController*a=[UIAlertController alertControllerWithTitle:@"排列到此章节之前" message:nil preferredStyle:UIAlertControllerStyleActionSheet];NSMutableArray*chapters=[self.db[@"chapters"]mutableCopy];[chapters addObjectsFromArray:[PMHookBackend contentSnapshot][@"chapters"] ?: @[]];for(NSDictionary*c in chapters){NSString*id=c[@"id"] ?: c[@"chapterCode"];if([id isEqualToString:identifier])continue;[a addAction:[UIAlertAction actionWithTitle:c[@"name"] ?: c[@"songInfo"][@"title"] style:UIAlertActionStyleDefault handler:^(UIAlertAction*x){NSMutableDictionary*d=[[PMContentStore.shared snapshot]mutableCopy];for(NSMutableDictionary*v in d[@"chapters"])if([v[@"id"]isEqualToString:identifier])v[@"before"]=id;[self save:d];}]];}a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:a animated:YES completion:nil];}
- (void)importFiles {
 if(self.busy)return;self.imageID=nil;
 PMDiagnosticsWrite("Content picker presenting (copy import)");
 UIDocumentPickerViewController*p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeData,UTTypeZIP] asCopy:YES];
 p.allowsMultipleSelection=YES;p.delegate=self;[self presentViewController:p animated:YES completion:nil];
}
- (void)documentPickerWasCancelled:(UIDocumentPickerViewController*)picker {
 if(self.pendingExports){[PMContentStore.shared cleanupExports:self.pendingExports];self.pendingExports=nil;}
 PMDiagnosticsWrite("Content picker cancelled");self.imageID=nil;
 [picker dismissViewControllerAnimated:YES completion:nil];
}
- (void)documentPicker:(UIDocumentPickerViewController*)picker didPickDocumentsAtURLs:(NSArray<NSURL*>*)urls {if(self.pendingExports){[PMContentStore.shared cleanupExports:self.pendingExports];self.pendingExports=nil;[picker dismissViewControllerAnimated:YES completion:nil];return;}if(self.busy||!urls.count)return;PMDiagnosticsWrite([NSString stringWithFormat:@"Content picker selected %lu files",(unsigned long)urls.count].UTF8String);self.busy=YES;NSString*imageID=self.imageID,*chapter=self.selectedChapter;BOOL imageIsChapter=self.imageIsChapter;self.imageID=nil;self.imageIsChapter=NO;NSArray<NSURL*>*selected=[urls copy];void (^start)(void)=^{if(imageID){NSURL*url=selected.firstObject;dispatch_async(self.worker,^{BOOL access=[url startAccessingSecurityScopedResource];UIImage*source=[UIImage imageWithContentsOfFile:url.path];if(access)[url stopAccessingSecurityScopedResource];dispatch_async(dispatch_get_main_queue(),^{if(!source){self.busy=NO;[self reload];[self message:@"无法读取封面图片"];return;}CGFloat aspect=imageIsChapter?1.35625:(16.0/9.0);PMImageCropController*crop=[[PMImageCropController alloc]initWithImage:source aspect:aspect completion:^(UIImage*result){self.busy=NO;if(result){NSError*saveError=nil;NSData*png=UIImagePNGRepresentation(result);BOOL saved=png&&[PMContentStore.shared replaceImageData:png identifier:imageID error:&saveError];[self reload];[self message:saved?@"封面已保存":(saveError.localizedDescription ?: @"封面保存失败")];}else[self reload];}];crop.allowsCompleteCover=YES;UINavigationController*nav=[[UINavigationController alloc]initWithRootViewController:crop];nav.modalPresentationStyle=UIModalPresentationFullScreen;[self presentViewController:nav animated:YES completion:nil];});});return;}self.navigationItem.prompt=@"正在导入文件…";dispatch_async(self.worker,^{NSMutableArray*errors=[NSMutableArray new];NSUInteger done=0;for(NSURL*url in selected){@autoreleasepool{NSError*e=nil;BOOL ok=NO;PMDiagnosticsWrite([NSString stringWithFormat:@"Content import begin: %@",url.lastPathComponent].UTF8String);@try{ok=[PMContentStore.shared importURL:url chapter:chapter error:&e];}@catch(NSException*exception){e=[NSError errorWithDomain:@"PhiMod.Import" code:1 userInfo:@{NSLocalizedDescriptionKey:exception.reason ?: exception.name}];}if(ok)done++;else[errors addObject:[NSString stringWithFormat:@"%@:%@",url.lastPathComponent,e.localizedDescription ?: @"失败"]];PMDiagnosticsWrite([NSString stringWithFormat:@"Content import %@: %@ %@",ok?@"ok":@"失败",url.lastPathComponent,e.localizedDescription ?: @""].UTF8String);}}dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[self reload];[self message:[NSString stringWithFormat:@"Completed %lu / %lu\n%@",(unsigned long)done,(unsigned long)selected.count,[errors componentsJoinedByString:@"\n"]]];});});};if(picker.presentingViewController)[picker dismissViewControllerAnimated:YES completion:start];else start();}
- (void)export:(NSString*)identifier chapter:(BOOL)chapter {if(self.busy)return;self.busy=YES;[self reload];dispatch_async(self.worker,^{NSError*e=nil;NSURL*url=nil;@autoreleasepool{url=chapter?[PMContentStore.shared exportChapter:identifier error:&e]:[PMContentStore.shared exportSong:identifier error:&e];}dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[self reload];if(!url){[self message:e.localizedDescription];return;}UIDocumentPickerViewController*p=[[UIDocumentPickerViewController alloc]initForExportingURLs:@[url] asCopy:YES];self.pendingExports=@[url];p.delegate=self;[self presentViewController:p animated:YES completion:nil];});});}
- (void)apply {if(self.busy)return;NSDictionary*r=[PMHookBackend contentCommand:@"apply" identifier:@"" slot:0];if([r[@"ok"] boolValue])[self dismissViewControllerAnimated:YES completion:nil];else[self message:r[@"message"]];}
@end
void PMShowContent(UIView*source,BOOL chapters){UIViewController*presenter=source.window.rootViewController;if(!presenter)return;while(presenter.presentedViewController)presenter=presenter.presentedViewController;PMContentController*c=[[PMContentController alloc]initWithStyle:UITableViewStyleInsetGrouped];UINavigationController*nav=[[UINavigationController alloc]initWithRootViewController:c];nav.modalPresentationStyle=UIModalPresentationFullScreen;[presenter presentViewController:nav animated:YES completion:^{c.pages.selectedSegmentIndex=chapters?1:0;[c reload];}];}
